cat > creator-college-junior-v9/app/styles.css <<'CSS'
:root{color-scheme:dark;--g:#f6cc74;--b:#6cddff;--m:#b8c5df;--l:rgba(255,255,255,.12)}*{box-sizing:border-box}body{margin:0;background:#050812;color:#f8f9fc;font-family:Inter,system-ui,-apple-system,sans-serif}button,input,textarea{font:inherit}.app{min-height:100vh;padding:22px 15px 60px;background:radial-gradient(circle at 12% 0,#173d7c 0,transparent 31%),radial-gradient(circle at 92% 7%,#512477 0,transparent 28%),#050812}.shell{max-width:880px;margin:auto}.brand{font-weight:950;letter-spacing:2px;color:var(--g);font-size:13px;margin-bottom:18px}.brand b{display:block;color:white;font-size:18px;letter-spacing:0;margin-top:4px}.card{padding:clamp(22px,5vw,42px);border:1px solid var(--l);border-radius:25px;background:linear-gradient(145deg,rgba(255,255,255,.085),rgba(255,255,255,.035));box-shadow:0 26px 80px rgba(0,0,0,.35)}.eye{color:var(--g);font-weight:900;font-size:12px;letter-spacing:2.4px}.hero{font-size:clamp(42px,9vw,78px);line-height:.95;letter-spacing:-3px;margin:12px 0 18px}.title{font-size:clamp(34px,7vw,54px);line-height:1;letter-spacing:-1.5px;margin:10px 0 16px}.lead{font-size:18px;line-height:1.55;color:var(--m);max-width:700px}.btn{border:0;border-radius:999px;padding:15px 20px;font-weight:900;cursor:pointer}.primary{background:linear-gradient(100deg,#f6ce76,#ffe9ae);color:#171109}.secondary{background:rgba(255,255,255,.08);border:1px solid var(--l);color:white}.btn:disabled{opacity:.4;cursor:not-allowed}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:25px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:11px;margin:20px 0}.choice{padding:17px;border:1px solid var(--l);border-radius:17px;background:rgba(255,255,255,.045);color:white;text-align:left;cursor:pointer}.choice.on{border-color:var(--b);background:rgba(82,155,255,.15)}.choice b{display:block;font-size:16px}.choice small{display:block;color:var(--m);margin-top:4px}.field{display:block;margin:17px 0}.field b{display:block;font-size:11px;letter-spacing:1.4px;margin-bottom:7px}.input,.area{width:100%;padding:15px;border-radius:15px;border:1px solid var(--l);background:rgba(0,0,0,.24);color:white;outline:none}.area{min-height:105px}.pills{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0}.pill{padding:9px 12px;border-radius:999px;border:1px solid var(--l);background:rgba(255,255,255,.05);color:white;cursor:pointer}.pill.on{border-color:#a978ff;background:rgba(169,120,255,.2)}.mix{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:21px 0}.mix>div,.tile{padding:18px;border-radius:18px;border:1px solid var(--l);background:rgba(255,255,255,.05)}.mix em{display:block;color:var(--g);font-size:26px;font-weight:950;font-style:normal}.id{margin:20px 0;padding:23px;border-radius:24px;border:1px solid rgba(246,204,116,.4);background:radial-gradient(circle at 90% 0,rgba(155,94,255,.32),transparent 35%),linear-gradient(145deg,#0f1b38,#080d19)}.id small{color:var(--g);font-weight:900;letter-spacing:1px}.avatar{font-size:55px;margin:20px 0 5px}.id h2{font-size:32px;margin:4px 0}.muted{color:var(--m)}.reward{padding:18px;border-radius:18px;background:rgba(66,190,110,.1);border:1px solid rgba(120,240,160,.25);margin:20px 0}.reward b{display:block;color:#88f0ad;font-size:18px}.campus{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:18px 0}.tile.lock{opacity:.52}.tile small{color:var(--g);font-weight:900}.progress{display:flex;gap:5px;margin-bottom:18px}.progress i{height:5px;flex:1;border-radius:8px;background:rgba(255,255,255,.1)}.progress i.on{background:linear-gradient(90deg,var(--g),var(--b))}.reset{background:none;border:0;color:#8390a8;text-decoration:underline;cursor:pointer;float:right}.schools{display:flex;gap:7px;flex-wrap:wrap;margin:14px 0}.schools span{font-size:12px;border:1px solid var(--l);border-radius:999px;padding:7px 9px}@media(max-width:620px){.grid,.mix,.campus{grid-template-columns:1fr}.actions .btn{width:100%}.hero{letter-spacing:-2px}}
