cat > creator-college-junior-v9/app/page.js <<'JS'
'use client';
import{useEffect,useMemo,useState}from'react';
const KEY='ccj-open-house-v2';
const schools={video:'Video & TV',voice:'Voice & Podcasting',design:'Design',stories:'Stories',ai:'AI & Digital Creation',business:'Creator Business',ideas:'Big Ideas'};
const picks=[['videos','🎥','Make videos',{video:3,voice:1,stories:1}],['design','🎨','Draw & design',{design:3,stories:1,business:1}],['invent','💡','Invent things',{ideas:3,ai:1,business:1}],['stories','📚','Tell stories',{stories:3,voice:1,video:1}],['tech','🧠','Build with technology',{ai:3,ideas:2}],['products','🛍️','Make things people love',{business:3,design:1,ideas:1}],['perform','🎙️','Talk & perform',{voice:3,video:2}],['worlds','🌎','Create worlds',{stories:2,design:1,ideas:2}]];
const blank={step:0,parent:'',email:'',creator:'',age:'8-10',picks:[],avatar:'🎥',styles:[],audience:'',problem:'',idea:'',name:'',credits:0};
function score(sel){let x={video:0,voice:0,design:0,stories:0,ai:0,business:0,ideas:0};sel.forEach(id=>{let p=picks.find(a=>a[0]===id);if(p)Object.entries(p[3]).forEach(([k,v])=>x[k]+=v)});return Object.entries(x).sort((a,b)=>b[1]-a[1]).slice(0,3)}
export default function App(){const[s,setS]=useState(blank),[ready,setReady]=useState(false);useEffect(()=>{try{let r=localStorage.getItem(KEY);if(r)setS({...blank,...JSON.parse(r)})}catch{}setReady(true)},[]);useEffect(()=>{if(ready)localStorage.setItem(KEY,JSON.stringify(s))},[s,ready]);const mix=useMemo(()=>score(s.picks),[s.picks]);const go=step=>setS(v=>({...v,step}));const patch=x=>setS(v=>({...v,...x}));const reset=()=>{localStorage.removeItem(KEY);setS(blank)};if(!ready)return null;return <main className="app"><div className="shell"><button className="reset" onClick={reset}>reset demo</button><div className="brand">CREATOR COLLEGE<b>JUNIOR • OPEN HOUSE</b></div>{s.step>0&&s.step<10&&<div className="progress">{[1,2,3,4,5,6,7,8,9].map(n=><i key={n} className={n<=s.step?'on':''}/>)}</div>}{s.step===0&&<Welcome go={go}/>} {s.step===1&&<Adult s={s} patch={patch} go={go}/>} {s.step===2&&<Creator s={s} patch={patch} go={go}/>} {s.step===3&&<Quiz s={s} patch={patch} go={go}/>} {s.step===4&&<Mix s={s} mix={mix} go={go}/>} {s.step===5&&<ID s={s} mix={mix} patch={patch} go={go}/>} {s.step===6&&<Mission s={s} patch={patch} finish={()=>setS(v=>({...v,step:7,credits:50}))}/>} {s.step===7&&<Celebrate s={s} go={go}/>} {s.step===8&&<Campus s={s} go={go}/>} {s.step===9&&<Parent s={s} mix={mix} go={go}/>} {s.step===10&&<Schools go={go}/>}</div></main>}
function Welcome({go}){return <section className="card"><div className="eye">FREE CREATOR OPEN HOUSE</div><h1 className="hero">Learn to Create<br/>in an AI World.</h1><p className="lead">You already have ideas. Creator College Junior helps you turn them into things people can see, hear, use, and share.</p><div className="schools">{Object.values(schools).map(x=><span key={x}>{x}</span>)}</div><div className="actions"><button className="btn primary" onClick={()=>go(1)}>START MY FREE OPEN HOUSE →</button><button className="btn secondary" onClick={()=>go(10)}>Explore 7 Schools</button></div><p className="muted">10–15 minutes • private by default • parent/grown-up check-in</p></section>}
function Adult({s,patch,go}){let ok=s.parent.trim()&&/\S+@\S+\.\S+/.test(s.email);return <section className="card"><div className="eye">GROWN-UP CHECK-IN</div><h1 className="title">First, a grown-up.</h1><p className="lead">Young creators don’t need their own email or public account. A grown-up stays in control.</p><label className="field"><b>GROWN-UP FIRST NAME</b><input className="input" value={s.parent} onChange={e=>patch({parent:e.target.value})}/></label><label className="field"><b>GROWN-UP EMAIL</b><input className="input" type="email" value={s.email} onChange={e=>patch({email:e.target.value})}/></label><div className="actions"><button className="btn secondary" onClick={()=>go(0)}>Back</button><button className="btn primary" disabled={!ok} onClick={()=>go(2)}>Continue to Campus</button></div></section>}
function Creator({s,patch,go}){return <section className="card"><div className="eye">VISITING CREATOR</div><h1 className="title">Who’s visiting Creator College?</h1><label className="field"><b>FIRST NAME OR NICKNAME</b><input className="input" value={s.creator} onChange={e=>patch({creator:e.target.value})}/></label><div className="grid">{['8-10','11-12'].map(a=><button key={a} className={'choice '+(s.age===a?'on':'')} onClick={()=>patch({age:a})}><b>Ages {a}</b><small>Junior creator lane</small></button>)}</div><button className="btn primary" disabled={!s.creator.trim()} onClick={()=>go(3)}>Discover My Creator Mix</button></section>}
function Quiz({s,patch,go}){function t(id){let a=s.picks.includes(id)?s.picks.filter(x=>x!==id):[...s.picks,id];if(a.length>3)a=a.slice(1);patch({picks:a})}return <section className="card"><div className="eye">CREATOR QUIZ</div><h1 className="title">What sounds like you?</h1><p className="lead">Pick three. There are no wrong answers.</p><div className="grid">{picks.map(([id,ic,l])=><button key={id} className={'choice '+(s.picks.includes(id)?'on':'')} onClick={()=>t(id)}><b>{ic} {l}</b><small>{s.picks.includes(id)?'Picked':'Tap to pick'}</small></button>)}</div><button className="btn primary" disabled={s.picks.length!==3} onClick={()=>go(4)}>Reveal My Creator Mix</button></section>}
function Mix({s,mix,go}){return <section className="card"><div className="eye">YOUR CREATOR MIX</div><h1 className="title">{s.creator}, look what we found.</h1><p className="lead">These are starting signals, not boxes. <b>You never have to pick just one.</b></p><div className="mix">{mix.map(([k,v],i)=><div key={k}><em>#{i+1}</em><b>{schools[k]}</b><p className="muted">Creator signal {v}</p></div>)}</div><button className="btn primary" onClick={()=>go(5)}>Build My Creator ID</button></section>}
function ID({s,mix,patch,go}){let av=['🎥','🎙️','🎨','💡','🚀','📚'];let styles=['Bold','Funny','Colorful','Smart','Futuristic','Sporty','Musical','Helpful'];function st(x){let a=s.styles.includes(x)?s.styles.filter(y=>y!==x):[...s.styles,x];patch({styles:a.slice(-3)})}return <section className="card"><div className="eye">CAMPUS PASS</div><h1 className="title">Make your Creator ID.</h1><div className="pills">{av.map(x=><button key={x} className={'pill '+(s.avatar===x?'on':'')} onClick={()=>patch({avatar:x})}>{x}</button>)}</div><div className="pills">{styles.map(x=><button key={x} className={'pill '+(s.styles.includes(x)?'on':'')} onClick={()=>st(x)}>{x}</button>)}</div><IdCard s={s} mix={mix}/><button className="btn primary" onClick={()=>go(6)}>Start My First Creator Mission</button></section>}
function IdCard({s,mix}){return <div className="id"><small>CREATOR COLLEGE JUNIOR • OPEN HOUSE</small><div className="avatar">{s.avatar}</div><h2>{s.creator||'Visiting Creator'}</h2><p className="muted">VISITING CREATOR • Ages {s.age}</p><div className="schools">{mix.map(([k])=><span key={k}>{schools[k]}</span>)}</div></div>}
function Mission({s,patch,finish}){let valid=s.audience&&s.problem.trim()&&s.idea.trim()&&s.name.trim();return <section className="card"><div className="eye">FIRST CREATOR MISSION • BIG IDEAS</div><h1 className="title">Invent Something That Makes Life Better.</h1><p className="lead">Creators notice something that could be easier, happier, smarter, or more fun—then imagine a solution.</p><div className="pills">{['Me','My Family','A Friend','Kids Like Me','Pets','Everybody'].map(x=><button key={x} className={'pill '+(s.audience===x?'on':'')} onClick={()=>patch({audience:x})}>{x}</button>)}</div><label className="field"><b>WHAT COULD BE BETTER OR MORE FUN?</b><textarea className="area" value={s.problem} onChange={e=>patch({problem:e.target.value})}/></label><label className="field"><b>WHAT COULD YOU INVENT?</b><textarea className="area" value={s.idea} onChange={e=>patch({idea:e.target.value})}/></label><label className="field"><b>WHAT IS IT CALLED?</b><input className="input" value={s.name} onChange={e=>patch({name:e.target.value})}/></label><button className="btn primary" disabled={!valid} onClick={finish}>That’s My Creation!</button></section>}
function Celebrate({s,go}){return <section className="card"><div style={{fontSize:78}}>🎉</div><div className="eye">MISSION COMPLETE</div><h1 className="title">You made something!</h1><p className="lead">{s.creator}, you noticed a problem, imagined a solution, and gave it a name. That’s creator work.</p><div className="reward"><b>🏅 OPEN HOUSE CREATOR BADGE</b><span>+50 Creator Credits</span></div><div className="id"><small>MY FIRST CREATOR IDEA • CREATED BY {s.creator.toUpperCase()}</small><div className="avatar">💡</div><h2>{s.name}</h2><p>{s.idea}</p><p className="muted">Made for: {s.audience}</p></div><button className="btn primary" onClick={()=>go(8)}>See My Creator Campus</button></section>}
function Campus({s,go}){return <section className="card"><div className="eye">WELCOME TO CREATOR CAMPUS</div><h1 className="title">Welcome, {s.creator}.</h1><div className="reward"><b>{s.avatar} Visiting Creator</b><span>{s.credits} Creator Credits • Creator ID + first creation saved locally</span></div><div className="campus"><div className="tile"><small>OPEN</small><b>Explore 7 Schools</b></div><div className="tile"><small>SAVED</small><b>My Creator Locker</b><p>{s.name}</p></div><div className="tile lock"><small>SEMESTER ONE</small><b>🎥 My First Show 🔒</b></div><div className="tile lock"><small>SEMESTER ONE</small><b>🛍️ My First Product 🔒</b></div><div className="tile lock"><small>SEMESTER ONE</small><b>🌎 Story World 🔒</b></div><div className="tile lock"><small>SEMESTER ONE</small><b>🤖 Build With AI 🔒</b></div></div><button className="btn primary" onClick={()=>go(9)}>SHOW MY GROWN-UP →</button></section>}
function Parent({s,mix,go}){return <section className="card"><div className="eye">FOR {s.parent.toUpperCase()} • GROWN-UP</div><h1 className="title">{s.creator} just completed Open House.</h1><p className="lead">They didn’t just watch something. They created something.</p><div className="mix">{mix.map(([k],i)=><div key={k}><em>#{i+1}</em><b>{schools[k]}</b></div>)}</div><div className="id"><small>FIRST CREATION</small><div className="avatar">💡</div><h2>{s.name}</h2><p>{s.idea}</p></div><div className="reward"><b>SEMESTER ONE • I CAN CREATE</b><span>6 missions • Creator Showcase • Digital diploma</span></div><div className="tile"><small>FOUNDING STUDENT STAGING OFFER</small><h2>$19 one-time</h2><p className="muted">The Shopify product remains DRAFT until auth/database staging is complete.</p></div><button className="btn primary" disabled>Semester One checkout is staged</button><div className="actions"><button className="btn secondary" onClick={()=>go(8)}>Back to Campus</button><button className="btn secondary" onClick={()=>go(0)}>Front Door</button></div></section>}
function Schools({go}){let icons=['🎥','🎙️','🎨','📚','🤖','🛍️','💡'];return <section className="card"><div className="eye">7 SCHOOLS • 1 CREATOR YOU</div><h1 className="title">Explore what you can create.</h1><div className="campus">{Object.values(schools).map((v,i)=><div className="tile" key={v}><small>SCHOOL {i+1}</small><b>{icons[i]} {v}</b></div>)}</div><button className="btn primary" onClick={()=>go(1)}>Start Free Open House</button></section>}
